"""Exact outputs captured before extraction; the stored baseline is never regenerated by tests."""
import gzip
import json
from pathlib import Path

from tests.seat_rule_cases import outputs
from orkboard.core import idea_talk, idea_sections, idea_accept
from orkboard.realm import seat_talk_rules, seat_section_rules, seat_join_rules, seat_accept_rules


def test_original_outputs():
    baseline = json.loads(gzip.decompress((Path(__file__).parent / 'fixtures/seat_rules_original.json.gz').read_bytes()))
    assert json.loads(json.dumps(outputs())) == baseline


def test_compatible_entry_points():
    for old, new, names in ((idea_talk, seat_talk_rules, ('rules', 'project_rules', 'CARDS', 'AFTER_RULE')),
                            (idea_sections, seat_section_rules, ('rules', 'WHY_FREE', 'WHY_CAUSE')),
                            (idea_sections, seat_join_rules, ('join_rules', 'MAX_FORKS', 'SAYS_CHARS', 'ABOUT_CHARS', 'GIST_CHARS')),
                            (idea_accept, seat_accept_rules, ('rules', 'ROUNDS', 'BACK_MAX', 'LINE_CHARS', 'LEARNED_MAX'))):
        for name in names:
            assert getattr(old, name) is getattr(new, name)
